export function icon(name, size = 16, extra = '') {
  const body = PATHS[name] || PATHS.circle;
  const s = document.createElement('span');
  s.className = 'ico ' + extra;
  s.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
  return s;
}
export const hasIcon = (n) => n in PATHS;
